// Map the incoming form fields to one clean lead object.
// Add your form's field names to the pick(...) lists if they differ.
return $input.all().map(({ json }) => {
  const b = json.body ?? json;
  const pick = (...keys) => {
    for (const k of keys) {
      const v = b[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };
  const email = pick('email', 'Email', 'work_email', 'emailAddress').toLowerCase();
  const lead = {
    leadId: 'L-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
    receivedAt: new Date().toISOString(),
    name: pick('name', 'full_name', 'fullName', 'Name'),
    email,
    company: pick('company', 'Company', 'company_name', 'organization'),
    website: pick('website', 'url', 'company_website'),
    role: pick('role', 'job_title', 'title'),
    budget: pick('budget', 'Budget', 'monthly_budget'),
    timeline: pick('timeline', 'start_date', 'when'),
    message: pick('message', 'Message', 'details', 'notes', 'project').slice(0, 3000),
    source: pick('source', 'utm_source') || 'website',
  };
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  lead.valid = emailOk && (lead.message !== '' || lead.company !== '');
  lead.error = !emailOk ? 'A valid email is required' : lead.valid ? '' : 'Please add your company or a short message';
  return { json: lead };
});

