// Validate the AI's JSON. If the AI failed or returned junk, keep the lead and mark it for review.
const HOT = 70;  // SET ME: score for "hot"
const WARM = 40; // SET ME: score for "warm"
const lead = $('Normalize Lead').item.json;
let ai = null;
let aiStatus = 'ok';
try {
  if ($json.error) throw new Error(typeof $json.error === 'string' ? $json.error : ($json.error.message || 'AI step failed'));
  const raw = String($json.text ?? '').replace(/```(json)?/g, '').trim();
  ai = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
} catch (e) {
  aiStatus = 'fallback: ' + String(e.message).slice(0, 120);
}
let score = Number(ai?.score);
score = Number.isFinite(score) ? Math.max(0, Math.min(100, Math.round(score))) : null;
const tier = score === null ? 'review' : score >= HOT ? 'hot' : score >= WARM ? 'warm' : 'cold';
const list = (v) => (Array.isArray(v) ? v.slice(0, 5).join('; ') : String(v ?? ''));
return { json: {
  leadId: lead.leadId, receivedAt: lead.receivedAt, name: lead.name, email: lead.email,
  company: lead.company, website: lead.website, role: lead.role, budget: lead.budget,
  timeline: lead.timeline, source: lead.source,
  score: score ?? '', tier,
  intent: String(ai?.intent ?? ''),
  summary: String(ai?.summary ?? '').slice(0, 400),
  fitReasons: list(ai?.fit_reasons),
  redFlags: list(ai?.red_flags),
  nextStep: String(ai?.suggested_next_step ?? ''),
  aiStatus,
  message: lead.message.slice(0, 1000),
} };

